import json
import re

from taf.rfrl.procedures.resources.python.json_delta_scf.exceptions import ParameterNotFound, ObjectsNotFound
from taf.rfrl.procedures.resources.python.logger import log_exception


def get_cell_info_from_delta(json_delta_file, operation="added"):
    """
    Acquires necessary info for manipulating cells objects using selenium from provided delta .json file
            {
                "MRBTS-50138/NRBTS-1/NRCELL-3": {
                "id": "3", "object_name": "MRBTS-50138/NRBTS-1", "object_class": "NRCELL"
                },
                "MRBTS-50138/LNBTS-1/LNCEL-1": {
                "id": "1", "object_name": "MRBTS-50138/LNBTS-1", "object_class": "LNCEL"
                 }
            }
    :param json_delta_file: (str) Full path to json delta from which data will be acquired
    :type json_delta_file: str
    :param operation: dictionary key of operation type from json delta file, "removed", "added" or "changed"
    :type operation: str
    :return: dict containing info for all cells from delta file
    :rtype: dict
    :raises ObjectsNotFound: when objects can't be found in JSON delta file for provided operation
    """

    return _get_cell_info_from_delta(json_delta_file, operation)


def get_cell_ids_list_from_delta_per_rat(json_delta_file, operation="added"):
    """
    Acquires dict of cell ids for each RAT from provided delta .json file

    :param json_delta_file: (str) Full path to json delta from which data will be acquired
    :type json_delta_file: str
    :param operation: dictionary key of operation type from json delta file, "removed", "added" or "changed"
    :type operation: str
    :return: dict of cell ids i.e. {'nr': [1, 2, 3], 'lte': [4, 5, 6]}
    :rtype: dict
    :raises ObjectsNotFound: when objects can't be found in JSON delta file for provided operation
    """

    cell_info = _get_cell_info_from_delta(json_delta_file, operation)
    cell_dict = {}

    for dist_name in cell_info.keys():
        cell_dict = _add_to_dict(
            key=_get_rat_name_depending_on_class(cell_info[dist_name]["object_class"]),
            value=int(cell_info[dist_name]["id"]),
            dictionary=cell_dict
        )

    return cell_dict


def get_cell_mapping_info_from_delta(json_delta_file, operation="added"):
    """
    Acquires necessary info for manipulating cells relations objects (CELLMAPING) using selenium from
    provided delta .json file
            {
                "MRBTS-50579/MNL-1/MNLENT-1/CELLMAPPING-1/LCELL-1": {
                "id": "1", "object_name": "MRBTS-50579/MNL-1/MNLENT-1/CELLMAPPING-1", "object_class": "LCELL"
                },
                "MRBTS-50579/MNL-1/MNLENT-1/CELLMAPPING-1/LCELNR-3": {
                "id": "3", "object_name": "MRBTS-50579/MNL-1/MNLENT-1/CELLMAPPING-1", "object_class": "LCELNR"
                }
            }
    :param json_delta_file: (str) Full path to json delta from which data will be acquired
    :type json_delta_file: str
    :param operation: dictionary key of operation type from json delta file, "removed", "added" or "changed"
    :type operation: str
    :return: dict containing info for all cells relations from delta file
    :rtype: dict
    :raises ObjectsNotFound: when objects can't be found in JSON delta file for provided operation
    """
    pattern = r'(LCELNR|LCELL|LCELW|LCELG)[-][^/]*$'

    return _get_object_info_based_on_pattern(json_delta_file, pattern, operation)


def get_nrcellgroup_info_from_delta(json_delta_file, operation="added"):
    """
    Acquires necessary info for manipulating nrcells group objects (NRCELLGRP) using selenium from
    provided delta .json file
            {
                "MRBTS-50579/NRBTS-50579/NRCELLGRP-1": {
                "id": "1", "object_name": "MRBTS-50579/NRBTS-50579", "object_class": "NRCELLGRP"
                },
                "MRBTS-50579/NRBTS-50579/NRCELLGRP-11": {
                "id": "11", "object_name": "MRBTS-50579/NRBTS-50579", "object_class": "NRCELLGRP"
                }
            }
    Additionally, exception will be logged when objects can't be found in JSON delta file for provided operation.

    :param json_delta_file: (str) Full path to json delta from which data will be acquired
    :type json_delta_file: str
    :param operation: dictionary key of operation type from json delta file, "removed", "added" or "changed"
    :type operation: str
    :return: dict containing info for all nrcells groups from delta file
    :rtype: dict
    """
    pattern = r'(NRCELLGRP-)[^/]*$'
    try:
        return _get_object_info_based_on_pattern(json_delta_file, pattern, operation)
    except ObjectsNotFound as ex:
        log_exception(f"Please ignore this message if missing NRCELLGRP object is intended. {str(ex)}.")
        return []


