def get_object_param_values(json_delta_file, operation, dist_name, param_name):
    """
    Returns either list or single value of desired param name for passed distName
    from provided delta .json file e.g.

    {
        'added': [
            {"dist_name": "MRBTS-50579/NRBTS-50579/NRDU-1", "lists": [
                {"items": [], "params": [{"name": None, "value": "none"}], "name": "carrierAggregationSupportList"},
                {"items": [], "params": [
                    {"name": None, "value": "1"}, {"name": None, "value": "2"},
                    {"name": None, "value": "3"}, {"name": None, "value": "11"}
                ], "name": "refNrCellGroup"}]
             }
        ]
    }

    For dist_name="MRBTS-50579/NRBTS-50579/NRDU-1" and param_name="refNrCellGroup"
    method will return ['1', '2', '3', '11']

    :param json_delta_file: (str) Full path to json delta from which data will be acquired
    :type json_delta_file: str
    :param operation: dictionary key of operation type from json delta file, "removed", "added" or "changed"
    :type operation: str
    :param dist_name: name of object in which param should be searched for
    :type dist_name: str
    :param param_name: name of param for which values should be returned
    :type param_name: str
    :return: values of desired param name located under provided distName
    :rtype: str or list[str]
    :raises ParameterNotFound: when parameter can't be found in provided JSON delta file
    """

    return _get_object_param_values(json_delta_file, operation, dist_name, param_name)


def _get_object_param_values(json_delta_file, operation, dist_name, param_name):
    with open(json_delta_file) as delta_file:
        delta_data = json.load(delta_file)

    for json_object in delta_data[operation]:
        if json_object["dist_name"] == dist_name:
            for p_type in ["lists", "params"]:
                for param in json_object[p_type]:
                    if param["name"] == param_name:
                        return [element["value"] for element in param["params"]] \
                            if p_type == "lists" else param["value"]

    raise ParameterNotFound("Parameter {} for {} can't be found in JSON delta file".format(param_name, dist_name))


def _get_cell_info_from_delta(json_delta_file, operation="added"):
    pattern = r'(NRCELL|LNCEL|WNCEL|GNCEL)[-][^/]*$'

    return _get_object_info_based_on_pattern(json_delta_file, pattern, operation)


def _get_object_info_based_on_pattern(json_delta_file, pattern, operation):
    """
    Returns dict containing desired dist names (that matches provided regex pattern) with necessary info
    for manipulating objects using selenium from provided delta .json file e.g.

    pattern = r'(NRCELLGRP-)[^/]*$'
    output =
            {
                "MRBTS-50579/NRBTS-50579/NRCELLGRP-1": {
                "id": "1", "object_name": "MRBTS-50579/NRBTS-50579", "object_class": "NRCELLGRP"
                },
                "MRBTS-50579/NRBTS-50579/NRCELLGRP-11": {
                "id": "11", "object_name": "MRBTS-50579/NRBTS-50579", "object_class": "NRCELLGRP"
                }
            }

    :param json_delta_file: Full path to json delta from which data will be acquired
    :type json_delta_file: str
    :param pattern: Regex pattern used in dist name matching
    :type pattern: str
    :param operation: dictionary key of operation type from json delta file, "removed", "added" or "changed"
    :type operation: str
    :return: dict containing info based on provided pattern and delta file
    :rtype: dict
    :raises ObjectsNotFound: when objects can't be found in JSON delta file for provided regex pattern and operation
    """
    with open(json_delta_file) as delta_file:
        delta_data = json.load(delta_file)

    obj = {}

    for json_object in delta_data[operation]:
        if re.search(pattern, json_object["dist_name"]):
            obj[json_object["dist_name"]] = {'id': json_object["dist_name"].split("-")[-1]}
            obj[json_object["dist_name"]].update(
                {'object_name': "/".join(json_object["dist_name"].split("/")[:-1])}
            )
            obj[json_object["dist_name"]].update(
                {'object_class': json_object["dist_name"].split("/")[-1].split("-")[0]}
            )

    if not obj:
        raise ObjectsNotFound(f"Looks like there are no objects for '{pattern}' regex pattern under "
                              f"'{operation}' operation in json delta file")

    return obj


def _get_rat_name_depending_on_class(cell_class):
    rat_dict = {"LNCEL": "lte", "NRCELL": "nr", "WNCEL": "wcdma", "GNCEL": "gsm"}
    return rat_dict[cell_class]


def _add_to_dict(key, value, dictionary):
    if key in dictionary:
        if value not in dictionary[key]:
            dictionary[key].append(value)
            dictionary[key] = sorted(dictionary[key])
    else:
        dictionary[key] = [value]

    return dictionary
